+class CompactionLoopGuard {
+  constructor({ client, isHeadless, qualityLog, shouldContinue, now, detectOptions }) {
+    this.client = client;
+    this.isHeadless = isHeadless || (() => false);
+    this.log = qualityLog || (() => {});
+    this.shouldContinue = shouldContinue;
+    this.now = now || Date.now;
